const authStageLabel=stage=>stage==='connected'?'Подключён':stage==='error'?'Вход не подтверждён':stage==='saving'?'Сохраняем сессию':'Окно входа открыто';
let connectionRequest=null;const authProgressState={};
const connectionErrors={NO_TOKEN:'Войди в аккаунт сервиса.',AUTH_EXPIRED:'Сессия истекла. Войди в аккаунт ещё раз.',AUTH_FAILED:'Сервис не подтвердил вход. Переподключи аккаунт.',AUTH_FORBIDDEN:'Сервис отклонил доступ к аккаунту.',CHECK_TIMEOUT:'Проверка заняла слишком много времени. Данные входа не удалены.',CHECK_NETWORK:'Не удалось проверить аккаунт из-за сети. Сессия сохранена.'};
refreshConnections=async function(force=true){if(!backend)return;const version=++statusGeneration;const stamp=$('#connectionsChecked');if(stamp)stamp.textContent='Проверяем сервисы…';if(!connectionRequest)connectionRequest=api('status'+(force?'?force=1':'')).finally(()=>connectionRequest=null);try{const data=await connectionRequest;if(version!==statusGeneration)return;serviceState=data.sources||{};for(const source of Object.keys(serviceNames)){const s=serviceState[source]||{},node=$('#state-'+source),detail=$('#detail-'+source),configured=data.configured?.[source],code=typeof s.error==='object'?s.error?.code:s.error;let label=s.pending?'Проверка не завершена':s.connected?(source==='soundcloud'&&s.accountConnected!==true?'Каталог подключён':'Подключён'):'Не подключён';if(node){node.textContent=label;node.classList.toggle('is-on',!!s.connected)}if(detail){const user=typeof s.user==='string'?s.user:s.user?.displayName||s.user?.name;detail.textContent=s.connected?(user||(source==='soundcloud'&&s.accountConnected!==true?'Публичный каталог доступен. Для личных лайков войди в аккаунт.':'Доступ к сервису подтверждён.')):(connectionErrors[code]||s.message||'Проверь вход и попробуй снова.')+(configured&&!s.connected?' Данные входа сохранены на устройстве.':'')}}if($('#connectionsChecked'))$('#connectionsChecked').textContent='Проверено в '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit'});for(const [source,p]of Object.entries(authProgressState)){const node=$('#state-'+source),detail=$('#detail-'+source);if(node)node.textContent=authStageLabel(p.stage);if(detail)detail.textContent=p.message}}catch(e){if(version!==statusGeneration)return;if($('#connectionsChecked'))$('#connectionsChecked').textContent='Проверка не удалась. Можно повторить.';for(const source of Object.keys(serviceNames)){const node=$('#state-'+source);if(node)node.textContent='Не удалось проверить'}toast('Не удалось обновить подключения. Проверь локальный сервер и повтори.')}};
const connectionsBeforeRecovery=connectionsScreen;connectionsScreen=function(){return connectionsBeforeRecovery().replace('<div class="service-summary">',`<div class="connection-recovery"><div><strong>Состояние подключений</strong><span id="connectionsChecked" role="status">Статусы обновляются автоматически после входа</span></div><div><button class="secondary" id="forceConnectionRefresh" ${!backend?'disabled':''}>↻ Обновить статусы</button><button class="secondary" id="reloadConnectionsPage">Перезагрузить страницу</button></div></div><div class="service-summary">`)};
const renderBeforeRecovery=render;render=function(){renderBeforeRecovery();if(page==='connections'&&window.playerDesktop)for(const button of document.querySelectorAll('[data-signin]'))button.insertAdjacentHTML('afterend',`<button class="secondary recheck-auth" data-recheck-source="${button.dataset.signin}">Я вошёл — проверить</button>`)};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='reloadConnectionsPage')location.reload();if(b.id==='forceConnectionRefresh'){b.disabled=true;try{await refreshConnections(true)}finally{b.disabled=false}}if(b.dataset.recheckSource){b.disabled=true;try{const result=await window.playerDesktop?.recheckAuth(b.dataset.recheckSource);if(result?.message)toast(result.message);await refreshConnections(true)}catch{toast('Не удалось проверить окно входа. Попробуй обновить страницу сервиса.')}finally{b.disabled=false}}});
window.playerDesktop?.onAuthProgress(data=>{authProgressState[data.source]=data;const node=$('#state-'+data.source),detail=$('#detail-'+data.source);if(node)node.textContent=authStageLabel(data.stage);if(detail)detail.textContent=data.message});
window.playerDesktop?.onAuthChanged(data=>{delete authProgressState[data.source];refreshConnections(true)});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&page==='connections'&&backend)refreshConnections(true)});window.addEventListener('focus',()=>{if(page==='connections'&&backend)refreshConnections(true)});
